/**
 * Rahino Design System — Border foundations (proposed)
 *
 * Decision: mostly borderless. Structure comes from spacing and surfaces;
 * borders are opt-in affordances for controls, dense data, and states.
 *
 * Color sources remain in the canonical color foundation:
 *   rds.color.edge.subtle   — optional dividers
 *   rds.color.edge.control  — functional control boundary
 *   rds.color.focus.ring    — independent keyboard focus color
 *
 * Do not duplicate color, surface, radius, or elevation values here.
 * Status: pending Rahino approval and cross-surface contrast validation.
 */

/** Widths for opt-in boundaries; do not draw these by default. */
export const BORDER_WIDTH = {
  /**
   * @token rds.border.width.default
   * @usage Optional table/section separator or necessary control outline.
   * @avoid Boxing every cell, default card borders, and keyboard focus.
   */
  default: "1px",

  /**
   * @token rds.border.width.strong
   * @usage Selection and drop-target attention rings when the component
   *        defines a distinct state color and non-color state cue.
   * @avoid General structural borders and keyboard focus; focus has its
   *        own geometry even when both widths are 2px.
   */
  strong: "2px",
} as const;

/** Focus is an independent outline; the color lives in rds.color.focus.ring. */
export const FOCUS_RING_GEOMETRY = {
  /**
   * @token rds.focus.ring.width
   * @usage 2px visible keyboard-focus outline (:focus-visible).
   * @avoid Treating the normal control border as the focus indicator.
   */
  width: "2px",
} as const;

