/**
 * Rahino Design System — Color foundations (review-ready source)
 *
 * Canonical naming follows the APPROVED three-layer token convention:
 *   rds.color.ink.primary          -> --rds-color-ink-primary
 *   rds.color.action.primary.bg.hover -> --rds-color-action-primary-bg-hover
 *   rds.color.status.error.fg     -> --rds-color-status-error-fg
 *
 * Source policy: the approved foundation files are in this folder. Naming
 * follows Rahino-Tokenization.md. The typed review collection is stored in
 * master-tokens/shared.tokens.json, light.tokens.json and dark.tokens.json;
 * review status and remaining decisions are in master-tokens/decisions.json.
 * This TypeScript export remains a foundation contract while canonical
 * adoption and output generation are finalized.
 *
 * USAGE NOTE: JSDoc makes individual roles reviewable but is NOT by itself a
 * DTCG-conformant typed token registry. The local master collection records
 * typed values and aliases but remains a draft. Final publishing must resolve
 * appearances and generate CSS, documentation and Figma mappings from the
 * adopted canonical source; those outputs are not claimed to exist here.
 * Never maintain a second handwritten semantic-palette table.
 *
 * Floating UI rule: neutral popovers, menus, tooltips, selection toolbars,
 * and dialogs use surface.raised with the appropriate elevation shadow.
 * Do not switch to surface.inverse just to make a layer stand out.
 * Their content uses the standard ink hierarchy for the active appearance.
 *
 * Accessibility: a token is not universally accessible in isolation; validate
 * the foreground/background/state/context pair. 4.5:1 is WCAG AA for normal
 * text, 3:1 for large text and applicable non-text UI identification.
 */

export type AppearanceName = "light" | "dark";

/** Light/dark value pair for appearance-aware foundation consumers. */
export interface Pair {
  light: string;
  dark: string;
}

const pair = (light: string, dark: string): Pair => ({ light, dark });
/**
 * @family rds.color.surface
 * Opaque, structural background roles. Different values can be equal today but
 * roles stay independent because they can evolve independently.
 * In product components, consume their CSS semantic variables, not raw HEX.
 */

export const SURFACE = {
  /**
   * @token rds.color.surface.canvas
   * @usage Root application/page background. The lowest structural
   *        surface, providing the backdrop for all other UI surfaces.
   * @avoid Cards, modal interiors, inputs, and floating overlays.
   */
  canvas: pair("#EFECED", "#121113"),

  /**
   * @token rds.color.surface.base
   * @usage Default content surface for cards, panels, and sections
   *        within the page. Provides a clean, solid background.
   * @avoid Inputs, floating overlays, and components requiring
   *        a visually recessed surface.
   */
  base: pair("#FFFFFF", "#1A191B"),

  /**
   * @token rds.color.surface.subtle
   * @usage Low-emphasis grouping within content surfaces,
   *        including alternate sections, section headers,
   *        list tracks, and secondary containers.
   * @avoid Unfocused inputs, modals, and prominent floating
   *        surfaces. Not intended to establish strong separation.
   */
  subtle: pair("#F8F6F7", "#232225"),

  /**
   * @token rds.color.surface.raised
   * @usage Neutral elevated containers: dialogs, popovers, dropdowns,
   *        context menus, tooltips, and floating selection/action toolbars.
   *        Pair with the appropriate shadow token to communicate elevation;
   *        keep standard ink colors inside the container.
   * @avoid Standard page content, cards, and input backgrounds.
   *        Do not use inverse color as an elevation treatment.
   */
  raised: pair("#FFFFFF", "#2B292D"),

  /**
   * @token rds.color.surface.sunken
   * @usage Recessed surfaces within a parent container, including
   *        unfocused text fields, selects, textareas, editable
   *        regions, inset controls, and progress track s.
   *        Provides background separation without borders.
   * @avoid Modals, cards, and floating overlays.
   *        Use ink.secondary for meaningful supporting text;
   *        reserve ink.tertiary for nonessential metadata.
   */
  sunken: pair("#ECE8EA", "#0E0D0F"),

  /**
   * @token rds.color.surface.inverse
   * @usage Intentionally high-contrast, solid neutral controls only,
   *        such as an explicitly emphasized neutral button.
   * @pair rds.color.ink.inverse
   * @avoid Popovers, tooltips, context menus, dropdowns, dialogs,
   *        floating selection/action toolbars, and notification containers.
   *        Never use inverse fill to signal elevation or floating position;
   *        use surface.raised and an elevation shadow instead.
   *        Also avoid general page surfaces, inputs, and brand actions.
   */
  inverse: pair("#211D20", "#EEEEF0"),
} as const;

/** Overlay dimming, not a surface or a veil film. */
export const SCRIM = {
  /**
   * @token rds.color.scrim.modal
   * @usage Backdrop dimming behind a modal/dialog that blocks the underlying UI.
   * @avoid Hover states, glass panels, or ordinary in-flow content backgrounds.
   * @a11y Check effective dimming in each mode; scrim alone must not carry text.
   */
  // Modal dimming is a distinct role from the veil recipes in Veil.ts.
  modal: pair("rgb(20 12 17 / 0.52)", "rgb(0 0 0 / 0.72)"),
} as const;

/** Foreground roles for text and icons; select by meaning and contrast context. */
export const INK = {
  /**
   * @token rds.color.ink.primary
   * @usage Main body text, headings, values, field content and primary labels.
   * @avoid Over branded solid controls; use on-brand there.
   */
  primary: pair("#211D20", "#EEEEF0"),
  /**
   * @token rds.color.ink.secondary
   * @usage Readable supporting text, including descriptions,
   *        helper text, notification content, and meaningful
   *        metadata. Provides clear hierarchy below primary
   *        text without compromising readability.
   * @avoid Disabled states, decorative labels, and reducing
   *        contrast through additional opacity.
   */
  secondary: pair("#5F585D", "#C0BDC6"),

  /**
   * @token rds.color.ink.tertiary
   * @usage Low-emphasis but readable text, including timestamps,
   *        placeholders, captions, and nonessential metadata.
   *        Maintains visual hierarchy while meeting WCAG AA
   *        for normal text on standard opaque RDS surfaces.
   * @avoid Essential descriptions, instructions, error messages,
   *        disabled states, and uncontrolled glass backgrounds.
   *        Do not apply additional opacity.
   */
  tertiary: pair("#6D656B", "#AAA6B0"),

  /**
   * @token rds.color.ink.disabled
   * @usage Text/labels of genuinely disabled, noninteractive controls.
   * @avoid Placeholder for an enabled input; not for text that remains actionable.
   * @a11y Inactive controls can be exempt from WCAG text-contrast minimums,
   *       but state must also be programmatically exposed.
   */
  disabled: pair("#AAA3A7", "#625F69"),
  /**
   * @token rds.color.ink.on-brand
   * @usage Text/icons on validated solid brand/action-primary fills.
   * @avoid Text on light brand-tinted surfaces; use brand.fg there instead.
   */
  "on-brand": pair("#FFFFFF", "#FFFFFF"),
  /**
   * @token rds.color.ink.inverse
   * @usage Text/icons only on intentionally inverse neutral-solid controls.
   * @pair rds.color.surface.inverse
   * @avoid Text/icons in floating UI containers (popovers, toolbars, menus,
   *        tooltips, dialogs); use ink.primary/secondary/tertiary on
   *        surface.raised instead. Not a general foreground role.
   */
  inverse: pair("#EEEEF0", "#211D20"),
} as const;

/** Brand expression. `seed` is an identity decision, not an interactive state. */
export const BRAND = {
  /**
   * @token rds.color.brand.seed
   * @usage Immutable corporate identity reference, brand signatures and recipes
   *        that explicitly require the original brand seed in either appearance.
   * @avoid Applying raw seed indiscriminately to text or every clickable control.
   */
  seed: pair("#631244", "#631244"),
  /**
   * @token rds.color.brand.bg
   * @usage Selected/highlighted branded container, low-intensity emphasis panel,
   *        or soft brand control at rest.
   * @avoid Mistaking a tinted plate for a solid primary call-to-action.
   */
  bg: pair("#F3ECF0", "#291823"),
  /**
   * @token rds.color.brand.bg-hover
   * @usage Pointer-hover state ONLY for an interactive brand.bg surface.
   * @avoid Applying persistent hover tint to static brand panels or touch-only UI.
   */
  "bg-hover": pair("#EADCE4", "#321A29"),
  /**
   * @token rds.color.brand.fg
   * @usage Branded text/icon emphasis on appropriate light/dark backgrounds,
   *        especially on brand.bg, soft brand controls and toned badges.
   * @avoid Solid brand action labels; those use action.primary.fg.
   */
  fg: pair("#631244", "#C7A4B6"),
} as const;

/**
 * @token rds.color.link.fg
 * @usage Link-colored text where an actual interactive hyperlink is present.
 * @avoid Color-only identification of links inside a paragraph; supply underline,
 *        focus treatment and hover states per the link recipe.
 */
export const LINK_FG = BRAND.fg;

/** Branded primary action state machine; keep states distinct from brand.seed. */
export const ACTION_PRIMARY_BG = {
  /**
   * @token rds.color.action.primary.bg.default
   * @usage Primary high-priority button/action background in its rest state.
   * @avoid Using for selected informational chips or static brand decoration.
   */
  default: pair("#631244", "#631244"),
  /**
   * @token rds.color.action.primary.bg.hover
   * @usage Pointer-hover state on a currently enabled primary action.
   * @avoid Applying as persistent selection or during keyboard focus only.
   */
  hover: pair("#400C2C", "#741A52"),
  /**
   * @token rds.color.action.primary.bg.pressed
   * @usage Temporary active/pressed feedback for enabled primary actions.
   * @avoid Treating `pressed` as a durable selected/toggled state.
   */
  pressed: pair("#1E0515", "#4A0D33"),
  /**
   * @token rds.color.action.primary.bg.disabled
   * @usage Inactive solid primary control fill; interaction must be disabled too.
   * @avoid Using for secondary/neutral disabled controls or muted text alone.
   */
  disabled: pair("#B28DA4", "#4A3742"),
} as const;

/**
 * @token rds.color.action.primary.fg
 * @usage Foreground of enabled solid primary action across rest/hover/pressed.
 * @avoid Presuming this foreground is AA compliant on the disabled fill; use
 *        the disabled component recipe and disabled semantic text behavior.
 */
export const ACTION_PRIMARY_FG = pair("#FFFFFF", "#FFFFFF");

/**
 * @token rds.color.focus.ring
 * @usage Visible keyboard focus ring, generally via :focus-visible and
 *        focus geometry tokens in Border.ts.
 * @avoid Hover decoration, validation error border, or a substitute for focus
 *        geometry / forced-colors treatment.
 */
export const FOCUS_RING = pair("#99507A", "#A9638B");

/** Neutral interaction overlays. Their RGBA is composited over a base surface. */
export const INTERACTION = {
  /**
   * @token rds.color.interaction.neutral.hover
   * @usage Subtle pointer-hover overlay on otherwise neutral interactive rows,
   *        list items or icon-button hit regions.
   * @avoid Standalone text color, solid fill, or a universally fixed rendered
   *        outcome regardless of the background color underneath.
   */
  "neutral-hover": pair("rgb(33 29 32 / 0.06)", "rgb(238 238 240 / 0.08)"),
  /**
   * @token rds.color.interaction.neutral.pressed
   * @usage Brief pressed/touch-down feedback on a neutral interactive surface.
   * @avoid Permanent selected state, validation warning, or drag overlay.
   */
  "neutral-pressed": pair("rgb(33 29 32 / 0.10)", "rgb(238 238 240 / 0.12)"),
} as const;

/**
 * @token rds.color.interaction.selected.surface
 * @usage Persistent BRANDED selection plate (e.g. active segmented option or
 *        selected category) when the component recipe specifies branded tone.
 * @alias rds.color.brand.bg (same value by explicit semantic reference).
 * @avoid Conflating this branded selection with neutral selection treatments.
 */
export const INTERACTION_SELECTED_SURFACE = BRAND.bg;

/** Optional structural dividers and functional control boundaries only. */
export const EDGE = {
  /**
   * @token rds.color.edge.subtle
   * @usage Optional 1px separators in dense tables or between adjacent panels
   *        when spacing and surface contrast are insufficient.
   * @avoid Default card borders, form-control identification, and focus rings.
   *        Decorative only; not required to meet 3:1 non-text contrast.
   */
  subtle: pair("rgb(15 23 42 / 0.12)", "rgb(255 255 255 / 0.10)"),

  /**
   * @token rds.color.edge.control
   * @usage 1px boundary for enabled inputs, selects, or secondary controls
   *        only when their filled treatment needs a clearer affordance.
   * @avoid Decorative containers, default card frames, or indicating focus,
   *        selection, or error by border color alone.
   * @a11y Validate >=3:1 against adjacent surfaces wherever the boundary
   *       is required for identification. The approved value is 3.81:1
   *       against dark surface.raised; check actual component adjacency.
   */
  control: pair("#7A8493", "#7A8493"),
} as const;

/**
 * Semantic feedback families. Each role is a separate decision:
 * bg = subtle panel; edge = feedback frame; fg = readable text/icon;
 * fill = solid feedback; on-fill = ink on THAT solid fill.
 * Not general substitutes for brand/action roles.
 */
export const STATUS = {
  success: {
    /**
     * @token rds.color.status.success.bg
     * @usage Positive alert/validation panel fill; not a primary action.
     */
    bg: pair("#EAF5EE", "#203B2A"),
    /**
     * @token rds.color.status.success.edge
     * @usage Border of positive feedback panel or field-success indication.
     */
    edge: pair("#ADD7BC", "#4F9166"),
    /**
     * @token rds.color.status.success.fg
     * @usage Success message, icon or state label on validated surfaces.
     */
    fg: pair("#216E43", "#87DCA4"),
    /**
     * @token rds.color.status.success.fill
     * @usage Solid positive badge/indicator or success-specific action recipe.
     */
    fill: pair("#2F7D50", "#348556"),
    /**
     * @token rds.color.status.success.on-fill
     * @usage Text/icons only on status.success.fill.
     */
    "on-fill": pair("#FFFFFF", "#FFFFFF"),
  },
  warning: {
    /**
     * @token rds.color.status.warning.bg
     * @usage Warning callout/banner background.
     */
    bg: pair("#FBF2E2", "#40341D"),
    /**
     * @token rds.color.status.warning.edge
     * @usage Warning field/alert border.
     */
    edge: pair("#E8C98C", "#9B7937"),
    /**
     * @token rds.color.status.warning.fg
     * @usage Warning text/icon; reserve for caution, not generic emphasis.
     */
    fg: pair("#8A5A12", "#F0C86F"),
    /**
     * @token rds.color.status.warning.fill
     * @usage Solid warning pill/badge or alert marker.
     */
    fill: pair("#9E6A19", "#BE882E"),
    /**
     * @token rds.color.status.warning.on-fill
     * @usage Text/icons on warning.fill; light/dark inks differ intentionally.
     */
    "on-fill": pair("#FFFFFF", "#1B1407"),
  },
  error: {
    /**
     * @token rds.color.status.error.bg
     * @usage Error callout/validation container background.
     */
    bg: pair("#FBEAEC", "#42262B"),
    /**
     * @token rds.color.status.error.edge
     * @usage Invalid field or error alert border.
     */
    edge: pair("#EDB3B8", "#AA5963"),
    /**
     * @token rds.color.status.error.fg
     * @usage Validation error text/icon; don't signal error with color alone.
     */
    fg: pair("#A33A43", "#F4979F"),
    /**
     * @token rds.color.status.error.fill
     * @usage Solid error badge; destructive button through a separate recipe.
     */
    fill: pair("#B54650", "#B94C57"),
    /**
     * @token rds.color.status.error.on-fill
     * @usage Text/icons on error.fill.
     */
    "on-fill": pair("#FFFFFF", "#FFFFFF"),
  },
  info: {
    /**
     * @token rds.color.status.info.bg
     * @usage Nonurgent informational banner/panel fill.
     */
    bg: pair("#EAF1F9", "#23354B"),
    /**
     * @token rds.color.status.info.edge
     * @usage Info border around a feedback block.
     */
    edge: pair("#B6CCE6", "#5A83AE"),
    /**
     * @token rds.color.status.info.fg
     * @usage Information label/icon; link styling also needs link affordance.
     */
    fg: pair("#345E91", "#86B9EE"),
    /**
     * @token rds.color.status.info.fill
     * @usage Solid informational badge/indicator.
     */
    fill: pair("#416FA8", "#4479B5"),
    /**
     * @token rds.color.status.info.on-fill
     * @usage Text/icons on info.fill.
     */
    "on-fill": pair("#FFFFFF", "#FFFFFF"),
  },
} as const;

/**
 * Appearance + accessibility resolution, NOT a third color theme. Intended
 * only for `prefers-contrast: more` / explicit enhanced contrast path; native
 * `forced-colors` should use system colors, not these custom HEX values.
 * All remaining semantic roles must still be checked in context.
 */
export const HIGH_CONTRAST = {
  light: {
    /** @usage High-contrast page backdrop. */
    canvas: "#FFFFFF",
    /** @usage High-contrast ordinary card background. */
    base: "#FFFFFF",
    /** @usage High-contrast essential foreground. */
    primary: "#211D20",
    /** @usage Higher-contrast supplemental foreground. */
    secondary: "#211D20",
    /** @usage More-legible low-emphasis foreground in high-contrast mode. */
    tertiary: "#625B60",
  },
  dark: {
    /** @usage High-contrast dark page backdrop. */
    canvas: "#0E0D0F",
    /** @usage High-contrast dark card background. */
    base: "#121113",
    /** @usage High-contrast dark essential foreground. */
    primary: "#FFFFFF",
    /** @usage High-contrast dark secondary foreground. */
    secondary: "#EEEEF0",
    /** @usage High-contrast dark tertiary foreground. */
    tertiary: "#B5B2BC",
  },
} as const;

/** Contrast references accept only opaque colors; translucent pairs need compositing. */
const referenceLuminance = (hex: string): number => {
  if (!/^#[0-9a-f]{6}$/i.test(hex)) {
    throw new Error("Contrast references require opaque six-digit hex colors.");
  }
  const channels = [1, 3, 5].map(index => parseInt(hex.slice(index, index + 2), 16) / 255);
  const linear = channels.map(value =>
    value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4,
  );
  return linear[0] * 0.2126 + linear[1] * 0.7152 + linear[2] * 0.0722;
};

const referenceContrast = (foreground: string, background: string): number => {
  const a = referenceLuminance(foreground);
  const b = referenceLuminance(background);
  return (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05);
};

type ReferenceInk = "primary" | "secondary" | "tertiary";
const contrastReferenceFor = (appearance: AppearanceName): Record<ReferenceInk, Record<string, number>> =>
  Object.fromEntries(
    (["primary", "secondary", "tertiary"] as const).map(ink => [
      ink,
      Object.fromEntries(
        (["canvas", "base", "subtle", "raised", "sunken"] as const).map(surface => [
          surface,
          Number(referenceContrast(INK[ink][appearance], SURFACE[surface][appearance]).toFixed(2)),
        ]),
      ),
    ]),
  ) as Record<ReferenceInk, Record<string, number>>;

/**
 * Derived reference table, not an independent palette or a usage permission.
 * Calculated automatically from the current INK/SURFACE pairs on module load.
 * Two-decimal figures are for reference; acceptance must compare full-precision
 * ratios against the role-specific minimum, including actual adjacent colors.
 */
export const CONTRAST_REFERENCE: Record<AppearanceName, Record<ReferenceInk, Record<string, number>>> = {
  light: contrastReferenceFor("light"),
  dark: contrastReferenceFor("dark"),
};

/**
 * @family rds.color.data.categorical
 * @usage Distinct, unordered data series in charts.
 *        Series 01 anchors the palette to Rahino Plum.
 *        Other colors provide controlled hue differentiation.
 * @rules Preserve series order across light/dark themes.
 *        Use solid colors for lines, points, and chart marks.
 *        Always provide labels or legends.
 * @avoid Status semantics, translucent line strokes,
 *        or relying on color alone to identify a series.
 */
/** Public chart slots use 01 onward; their identity stays the same across appearances. */
export const DATA_CATEGORICAL_TOKENS = {
  /** @token rds.color.data.categorical.01 @usage Plum — categorical chart slot 01. */
  "01": pair("#631244", "#E18FBD"),
  /** @token rds.color.data.categorical.02 @usage Teal — categorical chart slot 02. */
  "02": pair("#287569", "#74CCB4"),
  /** @token rds.color.data.categorical.03 @usage Blue — categorical chart slot 03. */
  "03": pair("#386EAA", "#85B7ED"),
  /** @token rds.color.data.categorical.04 @usage Amber — categorical chart slot 04. */
  "04": pair("#926119", "#E5B567"),
  /** @token rds.color.data.categorical.05 @usage Indigo — categorical chart slot 05. */
  "05": pair("#654D91", "#B8A1E6"),
  /** @token rds.color.data.categorical.06 @usage Coral — categorical chart slot 06. */
  "06": pair("#9B4D48", "#E9968D"),
  /** @token rds.color.data.categorical.07 @usage Slate — categorical chart slot 07. */
  "07": pair("#526C7B", "#A4BECD"),
  /** @token rds.color.data.categorical.08 @usage Olive — categorical chart slot 08. */
  "08": pair("#637437", "#BFCB7A"),
} as const;

/** Compatibility array: index 0 maps to public slot 01, index 1 to 02, and so on. */
export const DATA_CATEGORICAL: Pair[] = Object.values(DATA_CATEGORICAL_TOKENS);

/**
 * @family rds.color.data.sequential
 * @usage Five ordered intensity levels for one metric.
 *        Progresses from muted plum to strong plum.
 *        Suitable for heatmaps, intensity maps, and
 *        discretized magnitude visualizations.
 * @rules 01 = lowest intensity; 05 = highest intensity.
 *        Keep perceptual progression consistent.
 * @avoid Categorical series, status indicators,
 *        or interpreting low intensity as missing data.
 */
/** Public chart slots use 01 onward; their identity stays the same across appearances. */
export const DATA_SEQUENTIAL_TOKENS = {
  /** @token rds.color.data.sequential.01 @usage Lowest — sequential chart slot 01. */
  "01": pair("#966883", "#A7839B"),
  /** @token rds.color.data.sequential.02 @usage Low — sequential chart slot 02. */
  "02": pair("#8C5776", "#B48BA6"),
  /** @token rds.color.data.sequential.03 @usage Medium — sequential chart slot 03. */
  "03": pair("#824465", "#C89CB6"),
  /** @token rds.color.data.sequential.04 @usage High — sequential chart slot 04. */
  "04": pair("#752C55", "#D9A7C3"),
  /** @token rds.color.data.sequential.05 @usage Highest — sequential chart slot 05. */
  "05": pair("#631244", "#E7B6D0"),
} as const;

/** Compatibility array: index 0 maps to public slot 01, index 1 to 02, and so on. */
export const DATA_SEQUENTIAL: Pair[] = Object.values(DATA_SEQUENTIAL_TOKENS);

/**
 * @family rds.color.data.diverging
 * @usage Five ordered levels around a meaningful midpoint.
 *        Teal represents one pole, plum the opposite.
 *        Neutral gray represents the center.
 * @rules 01/05 = opposite extremes; 03 = midpoint.
 *        Label the meaning of each pole explicitly.
 *        Use primarily for filled data visualizations.
 * @avoid Unordered categories, automatic success/error
 *        meanings, and using pale midpoint fills as
 *        standalone strokes or text colors.
 */
/** Public chart slots use 01 onward; their identity stays the same across appearances. */
export const DATA_DIVERGING_TOKENS = {
  /** @token rds.color.data.diverging.01 @usage First extreme — diverging chart slot 01. */
  "01": pair("#246F67", "#8AD3BF"),
  /** @token rds.color.data.diverging.02 @usage First moderate — diverging chart slot 02. */
  "02": pair("#64988D", "#58968A"),
  /** @token rds.color.data.diverging.03 @usage Neutral midpoint — diverging chart slot 03. */
  "03": pair("#CAC2C7", "#5E585F"),
  /** @token rds.color.data.diverging.04 @usage Second moderate — diverging chart slot 04. */
  "04": pair("#9B5878", "#A47891"),
  /** @token rds.color.data.diverging.05 @usage Second extreme — diverging chart slot 05. */
  "05": pair("#631244", "#E18FBD"),
} as const;

/** Compatibility array: index 0 maps to public slot 01, index 1 to 02, and so on. */
export const DATA_DIVERGING: Pair[] = Object.values(DATA_DIVERGING_TOKENS);

/**
 * @token rds.color.data.on-fill
 * @usage Foreground for text/icons inside solid
 *        categorical chart marks only, after contrast
 *        validation against the selected series color.
 * @avoid Tooltip text, sequential/diverging marks,
 *        translucent fills, or arbitrary backgrounds.
 */
export const DATA_ON_FILL = pair("#FFFFFF", "#211D20");

/**
 * Presentation-only decorative recipes; do not use them for product controls.
 * Brand light/dark are approved variants of one background that follows the
 * active appearance. The theme-neutral role, gradient storage and generated
 * theme selection are deferred to presentation design work. Preserve these
 * exports and artwork until that migration. Atmosphere is a separate recipe.
 */
export const PRESENTATION_GRADIENTS = {
  /**
   * @token rds.color.presentation.gradient.brand-dark
   * @usage Dark appearance of the theme-following brand hero background; not a form control.
   */
  "brand-dark":
    "linear-gradient(135deg, #121113 0%, #291823 65%, #631244 100%)",
  /**
   * @token rds.color.presentation.gradient.brand-light
   * @usage Light appearance of the theme-following brand hero background; not a content card.
   */
  "brand-light":
    "linear-gradient(135deg, #FFFFFF 0%, #F3ECF0 65%, #EADCE4 100%)",
  /**
   * @token rds.color.presentation.gradient.atmosphere
   * @usage Optional low-emphasis ambient hero decoration.
   */
  atmosphere:
    "radial-gradient(ellipse at 30% 20%, rgb(99 18 68 / 0.16), transparent 65%)",
} as const;

Spacing.ts.text:
/**
 * Rahino Design System — Spacing foundations
 *
 * Source: Spacing.md
 * Reference: Adobe Spectrum 2 layout spacing principles.
 *
 * Reference: ref.space.16 -> --ref-space-16 -> 16px.
 * Shared: rds.space.300 -> --rds-space-300 -> {ref.space.16}.
 * Reference and shared spacing use the standard ref and rds layer prefixes.
 * Reference names state their physical size; shared indexes are scale labels.
 *
 * This foundation defines 17 reference values and 17 shared aliases. Positive
 * indexes follow Spectrum; index 0 preserves Rahino's zero-spacing reset.
 * Components use shared aliases; component-specific aliases, density
 * recipes and sizing rules are defined when their components are approved.
 *
 * Supported density modes: Regular (default) and Spacious (opt-in where useful).
 * Compact is removed; not every component needs both modes. Density must not
 * automatically resize nested controls, typography, or line-height.
 *
 * Responsive components select different existing tokens when needed,
 * preferably based on container space. Don't scale all spacing automatically
 * or create mobile/desktop primitive scales. Exceptional fluid page-level
 * calculations may use clamp() in a documented layout recipe; no global
 * fluid-spacing token is defined.
 *
 * JSDoc documents the intended contract; this file is not a DTCG registry.
 */

/**
 * @family ref.space
 * @layer reference
 * @usage Fixed spacing reference values used by shared aliases and recipes.
 * @rules Select an existing value by relationship and available space.
 *        1px and 2px are exceptional optical/fine adjustments, not standard
 *        layout gaps. Add values only when a real use case justifies them.
 * @avoid Arbitrary in-between values in ordinary component spacing.
 */
export const SPACE = {
  /** @token ref.space.0  @usage No spacing / explicitly reset a gap. */
  0: "0px",
  /** @token ref.space.1  @usage Exceptional optical adjustment only. */
  1: "1px",
  /** @token ref.space.2  @usage Very small internal adjustment only. */
  2: "2px",
  /** @token ref.space.4  @usage Closely related labels and details. */
  4: "4px",
  /** @token ref.space.6  @usage Fine internal component spacing. */
  6: "6px",
  /** @token ref.space.8  @usage Icon–label and other related-element gaps. */
  8: "8px",
  /** @token ref.space.12 @usage Small component or group gaps. */
  12: "12px",
  /** @token ref.space.16 @usage Independent fields and small containers. */
  16: "16px",
  /** @token ref.space.20 @usage Intermediate internal padding. */
  20: "20px",
  /** @token ref.space.24 @usage Standard panels and content groups. */
  24: "24px",
  /** @token ref.space.32 @usage Spacious panels and major groups. */
  32: "32px",
  /** @token ref.space.40 @usage Larger layout separation. */
  40: "40px",
  /** @token ref.space.48 @usage Page sections. */
  48: "48px",
  /** @token ref.space.56 @usage Larger section separation. */
  56: "56px",
  /** @token ref.space.64 @usage Major layout regions. */
  64: "64px",
  /** @token ref.space.80 @usage Large-scale composition. */
  80: "80px",
  /** @token ref.space.96 @usage Exceptional large layouts. */
  96: "96px",
} as const;

/**
 * @family rds.space
 * @layer shared
 * Spectrum global spacing indexes, backed by ref.space.<px> references.
 * Index 0 is Rahino's reset extension; it is not in Spectrum's positive scale.
 */
export const SPACING = {
  /** @token rds.space.0 @layer shared @alias ref.space.0 @usage Remove spacing. */
  0: SPACE[0],
  /** @token rds.space.25 @layer shared @alias ref.space.1 @usage Exceptional optical adjustments. */
  25: SPACE[1],
  /** @token rds.space.50 @layer shared @alias ref.space.2 @usage Very small internal adjustments. */
  50: SPACE[2],
  /** @token rds.space.75 @layer shared @alias ref.space.4 @usage Tight label relationships. */
  75: SPACE[4],
  /** @token rds.space.85 @layer shared @alias ref.space.6 @usage Fine component spacing. */
  85: SPACE[6],
  /** @token rds.space.100 @layer shared @alias ref.space.8 @usage Icon-label gaps, related elements. */
  100: SPACE[8],
  /** @token rds.space.200 @layer shared @alias ref.space.12 @usage Small component and group gaps. */
  200: SPACE[12],
  /** @token rds.space.300 @layer shared @alias ref.space.16 @usage Fields, small containers. */
  300: SPACE[16],
  /** @token rds.space.350 @layer shared @alias ref.space.20 @usage Intermediate padding. */
  350: SPACE[20],
  /** @token rds.space.400 @layer shared @alias ref.space.24 @usage Standard containers, content groups. */
  400: SPACE[24],
  /** @token rds.space.500 @layer shared @alias ref.space.32 @usage Spacious containers, major groups. */
  500: SPACE[32],
  /** @token rds.space.600 @layer shared @alias ref.space.40 @usage Larger layout separation. */
  600: SPACE[40],
  /** @token rds.space.700 @layer shared @alias ref.space.48 @usage Page sections. */
  700: SPACE[48],
  /** @token rds.space.750 @layer shared @alias ref.space.56 @usage Larger section separation. */
  750: SPACE[56],
  /** @token rds.space.800 @layer shared @alias ref.space.64 @usage Major layout regions. */
  800: SPACE[64],
  /** @token rds.space.900 @layer shared @alias ref.space.80 @usage Large-scale composition. */
  900: SPACE[80],
  /** @token rds.space.1000 @layer shared @alias ref.space.96 @usage Exceptional large layouts. */
  1000: SPACE[96],
} as const;

Typography.ts.text:
/**
 * Rahino Design System — Typography foundations (review-ready source)
 *
 * Source: Rahino-Typography.md (current documented decisions).
 * Naming: rds.type.caption-sm -> --rds-type-caption-sm-* (size/weight/line-height).
 *
 * One semantic scale for desktop, tablet and phone. Only heading-page and
 * display use fluid font sizes. Choose a role for the content and available
 * space, not a separate mobile font-size set.
 *
 * Persian uses IRANYekanX; English uses Roboto Condensed. The English font
 * deliberately looks denser, but BOTH languages use the exact same size,
 * weight and line-height for each role. Mixed-script content inherits the
 * parent role's metrics; only the font family changes with the script.
 *
 * Scope: documented foundation values and usage contracts, not a CSS generator
 * or a DTCG-compliant token registry. Check the implementation against the
 * approved typography documentation before publication.
 */

/** Language-specific font stacks. No language-specific typography scale. */
export const FONT_FAMILY = {
  /**
   * @token rds.font.family.fa
   * @usage Persian interface text, paragraphs and headings.
   */
  fa: "IRANYekanX, sans-serif",

  /**
   * @token rds.font.family.latin
   * @usage English text, with the same role metrics as Persian.
   * @note Roboto Condensed's denser appearance is intentional.
   */
  latin: '"Roboto Condensed", sans-serif',

  /**
   * @token rds.font.family.code
   * @usage Standalone code, commands and technical literals only.
   * @avoid Regular interface text or decorative headlines.
   */
  code: "ui-monospace, SFMono-Regular, Consolas, monospace",
} as const;

/** Only the semantic weights used by the current typography roles. */
export const FONT_WEIGHT = {
  /** @token rds.font.weight.regular @usage Body, UI text and captions. */
  regular: 400,
  /** @token rds.font.weight.medium @usage Labels and control text. */
  medium: 500,
  /** @token rds.font.weight.semibold @usage Titles and section headings. */
  semibold: 600,
  /** @token rds.font.weight.bold @usage Page headings and display text. */
  bold: 700,
} as const;

/**
 * @family rds.type.line-height
 * Shared Persian/English unitless multipliers. In Figma, 1.8 means 180%.
 * A profile expresses text behavior; the complete semantic role is the token
 * that the component should consume.
 */
export const LINE_HEIGHT = {
  /** @token rds.type.line-height.ui @usage Short interface text and controls. */
  ui: 1.8,
  /** @token rds.type.line-height.reading @usage Multi-line reading content. */
  reading: 1.95,
  /** @token rds.type.line-height.heading @usage Structural headings and titles. */
  heading: 1.7,
  /** @token rds.type.line-height.display @usage Expressive large text. */
  display: 1.6,
  /** @token rds.type.line-height.fixed @usage Standalone code only. */
  fixed: 1.6,
} as const;

export type TypographyProfile = keyof typeof LINE_HEIGHT;

export interface TypographyStyle {
  fontSize: string; // rem or clamp(); responsive to root font size
  fontWeight: number;
  lineHeight: number; // unitless, identical in Persian and English
  profile: TypographyProfile;
  fontFamily?: string; // only overridden for standalone code
}

const style = (
  fontSize: string,
  fontWeight: number,
  profile: TypographyProfile,
): TypographyStyle => ({
  fontSize,
  fontWeight,
  lineHeight: LINE_HEIGHT[profile],
  profile,
});

/**
 * @family rds.type
 * Each semantic token resolves size + weight + line-height together.
 * Base definitions retain their existing API. Use TYPOGRAPHY_BY_SCRIPT to
 * bind the approved font family to the content script; do not independently
 * change metrics for English or smaller screens.
 * @rules No fixed-height clipping. Keep essential UI text >=14px at a 16px
 *        root; 12px captions are for optional information only.
 */
export const TYPOGRAPHY = {
  /**
   * @token rds.type.caption-sm
   * @usage Optional timestamps, update notes and minor chart metadata.
   * @avoid Essential information, errors and interactive actions.
   */
  "caption-sm": style("0.75rem", FONT_WEIGHT.regular, "ui"),

  /**
   * @token rds.type.caption-md
   * @usage Secondary metadata, card bylines, dates and status details.
   * @avoid Main content and interactive labels.
   */
  "caption-md": style("0.875rem", FONT_WEIGHT.regular, "ui"),

  /**
   * @token rds.type.ui-sm
   * @usage Compact lists, table cells, filter values and short secondary UI text.
   * @avoid Paragraphs and primary mobile actions.
   */
  "ui-sm": style("0.875rem", FONT_WEIGHT.regular, "ui"),

  /**
   * @token rds.type.ui-md
   * @usage Main navigation, menu items, list content and selection values.
   * @avoid Headings and long-form paragraphs.
   */
  "ui-md": style("1rem", FONT_WEIGHT.regular, "ui"),

  /**
   * @token rds.type.label-sm
   * @usage Compact buttons, chips, column labels and small/medium controls.
   * @avoid Long descriptions and prominent mobile calls to action.
   */
  "label-sm": style("0.875rem", FONT_WEIGHT.medium, "ui"),

  /**
   * @token rds.type.label-md
   * @usage Form labels, primary buttons, tabs and prominent touch controls.
   * @avoid Paragraphs and decorative headings.
   */
  "label-md": style("1rem", FONT_WEIGHT.medium, "ui"),

  /**
   * @token rds.type.body-sm
   * @usage Multi-line help, validation explanations and supporting descriptions.
   * @avoid Short table values and control labels.
   */
  "body-sm": style("0.875rem", FONT_WEIGHT.regular, "reading"),

  /**
   * @token rds.type.body-md
   * @usage Default paragraphs, guides, reports and dialog explanations.
   * @avoid Dense rows, menu labels and button text.
   */
  "body-md": style("1rem", FONT_WEIGHT.regular, "reading"),

  /**
   * @token rds.type.body-lg
   * @usage Short introductions, onboarding leads and prominent explanations.
   * @avoid Long mobile paragraphs and compact cards.
   */
  "body-lg": style("1.125rem", FONT_WEIGHT.regular, "reading"),

  /**
   * @token rds.type.title-sm
   * @usage Task/card titles, list-item names and compact mobile group headings.
   * @avoid The main page title.
   */
  "title-sm": style("1rem", FONT_WEIGHT.semibold, "heading"),

  /**
   * @token rds.type.title-md
   * @usage Dialogs, sheets, panels, large cards and roomy KPI values.
   * @avoid Repeated dense rows and narrow KPI columns.
   */
  "title-md": style("1.25rem", FONT_WEIGHT.semibold, "heading"),

  /**
   * @token rds.type.heading-section
   * @usage Major page sections and substantial report sections.
   * @avoid Small cards, mobile dialogs and minor subsections;
   *        use title-md for compact section headers.
   */
  "heading-section": style("1.5rem", FONT_WEIGHT.semibold, "heading"),

  /**
   * @token rds.type.heading-page
   * @usage Primary page heading, normally once per page. Fluid 24–32px
   *        at a 16px root; allow wrapping on small screens.
   * @avoid Card, sheet and nested-section titles.
   */
  "heading-page": style(
    "clamp(1.5rem, calc(1.357143rem + 0.714286vw), 2rem)",
    FONT_WEIGHT.bold,
    "heading",
  ),

  /**
   * @token rds.type.display
   * @usage Marketing heroes, welcome screens and expressive moments.
   *        Fluid 32–64px at a 16px root.
   * @avoid Everyday dashboards, forms and routine app pages.
   */
  display: style(
    "clamp(2rem, calc(1.428571rem + 2.857143vw), 4rem)",
    FONT_WEIGHT.bold,
    "display",
  ),

  /**
   * @token rds.type.input-touch
   * @usage Editable field values and placeholders on touch devices;
   *        remains 16px across screen sizes.
   * @avoid Input labels, helper text and buttons.
   */
  "input-touch": style("1rem", FONT_WEIGHT.regular, "ui"),

  /**
   * @token rds.type.code
   * @usage Standalone code snippets, commands and technical literals in LTR.
   * @avoid General copy. Inline code inherits parent line-height.
   */
  code: {
    ...style("0.875rem", FONT_WEIGHT.regular, "fixed"),
    fontFamily: FONT_FAMILY.code,
  },
} as const satisfies Record<string, TypographyStyle>;

export type TypographyRole = keyof typeof TYPOGRAPHY;

type ResolvedTypographyStyles = Readonly<Record<
  TypographyRole,
  TypographyStyle & { fontFamily: string }
>>;

// Derive complete styles without copying metrics or language-specific scales.
// Existing explicit font overrides (standalone code) take precedence.
const withFontFamily = (fontFamily: string): ResolvedTypographyStyles =>
  Object.fromEntries(
    Object.entries(TYPOGRAPHY).map(([role, definition]) => [
      role,
      { ...definition, fontFamily: definition.fontFamily ?? fontFamily },
    ]),
  ) as ResolvedTypographyStyles;

/**
 * Complete styles bound to the approved content-script font selection.
 * Use TYPOGRAPHY_BY_SCRIPT.fa[role] for Persian and .latin[role] for English.
 * All role metrics are inherited unchanged from TYPOGRAPHY; code stays mono.
 * This does not detect scripts or change direction. Select the appropriate
 * style for each text run; inline language changes keep their parent metrics.
 */
export const TYPOGRAPHY_BY_SCRIPT = {
  fa: withFontFamily(FONT_FAMILY.fa),
  latin: withFontFamily(FONT_FAMILY.latin),
} as const;

const READING_MEASURE = "42rem" as const;

/**
 * @family rds.type.layout
 * Reading measure and approved text-layout relationships. Apply via reading
 * and interface recipes, not implicit margins inside TYPOGRAPHY roles.
 * The paragraph recipe applies only to consecutive reading paragraphs;
 * ordinary interface-element gaps use shared spacing tokens.
 */
export const TEXT_LAYOUT = {
  measure: {
    /** @token rds.type.layout.measure.reading @usage Single maximum for long-form text; shrink to available width. */
    reading: READING_MEASURE,
    /**
     * @token rds.type.layout.measure.wide
     * @alias rds.type.layout.measure.reading
     * @usage Compatibility alias only; not a separate wider reading preset.
     * @deprecated Use measure.reading. Remove in the next breaking release
     *             after external consumer migration is verified; no new usage.
     */
    wide: READING_MEASURE,
  },
  gap: {
    /**
     * @token rds.type.layout.gap.paragraph
     * @usage Between consecutive paragraphs in reading content only.
     * @representation CSS recipe; 1em follows the paragraph font size.
     * @rules Apply once between adjacent paragraphs, in their font-size context.
     *        Use shared spacing tokens for interface-element gaps.
     *        Preserve user spacing overrides; do not freeze this to 16px.
     */
    paragraph: "1em",
    /** @token rds.type.layout.gap.title-description @usage Title to description. */
    "title-description": "8px",
    /** @token rds.type.layout.gap.section-content @usage Section title to its content. */
    "section-content": "16px",
  },
} as const;

/**
 * Implementation notes:
 * - Persian: letter-spacing: 0; text-align: start. Code: direction: ltr.
 * - Keep English and Persian at the SAME line-height and font size.
 * - On phone, select suitable roles and responsive layouts; do not shrink fonts.
 * - Use semantic HTML heading order independently of visual typography role.
 * - At 320 CSS px, with text at 200% and user text-spacing overrides, text
 *   must wrap or containers grow instead of clipping/overlapping content.
 * - Experimental tighter profile values are NOT adopted.
 */

