/**
 * Rahino Design System — Veil foundations (review-ready source)
 *
 * Canonical token paths:
 *   rds.veil.100.color   -> --rds-veil-100-color
 *   rds.veil.100.blur    -> --rds-veil-100-blur
 *   rds.veil.scrim.color -> --rds-veil-scrim-color
 *   rds.veil.scrim.blur  -> --rds-veil-scrim-blur
 *
 *
 * These are presentation treatments, not opaque semantic surfaces.
 * Use semantic text colors only after checking effective contrast against
 * the actual composited backdrop. Provide an opaque fallback when blur
 * is unsupported, in forced-colors mode, or in reduced-transparency mode.
 *
 *
 * JSDoc describes usage; production DTCG exports should define typed
 * color/blur values and derive CSS and Figma values from one registry.
 */

export type AppearanceName = "light" | "dark";

/** Light/Dark projection used by the existing RDS foundations pattern. */
export interface Pair {
  light: string;
  dark: string;
}

const pair = (light: string, dark: string): Pair => ({ light, dark });

/** A paired translucent fill and backdrop blur, applied to the same layer. */
export interface VeilTreatment {
  color: Pair;
  blur: string;
}

/**
 * @family rds.veil
 * Translucent glass treatments ordered from atmospheric (100) to focused (500).
 * Higher numbers increase background opacity while reducing blur radius.
 *
 * Apply with background-color + backdrop-filter: blur(...).
 * Never use CSS opacity on the whole component: it fades its children too.
 * Shadows, foreground colors, and borders remain separate design decisions.
 */
export const VEIL = {
  /**
   * @group rds.veil.100
   * @role Atmospheric
   * @usage Decorative glass, subtle background effects, non-interactive layers.
   * @avoid Content-bearing controls, tooltips, or overlays requiring readability.
   */
  "100": {
    /** @token rds.veil.100.color @usage Background fill with alpha already included. */
    color: pair("rgb(255 255 255 / 0.04)", "rgb(43 43 43 / 0.04)"),
    /** @token rds.veil.100.blur @usage Backdrop blur applied to the same layer. */
    blur: "64px",
  },

  /**
   * @group rds.veil.200
   * @role Ambient
   * @usage Background overlays and atmospheric floating layers.
   * @avoid Essential UI, text-heavy panels, and standalone interactive controls.
   */
  "200": {
    /** @token rds.veil.200.color @usage Background fill with alpha already included. */
    color: pair("rgb(255 255 255 / 0.18)", "rgb(37 37 37 / 0.18)"),
    /** @token rds.veil.200.blur @usage Backdrop blur applied to the same layer. */
    blur: "48px",
  },

  /**
   * @group rds.veil.300
   * @role Lightweight
   * @usage Short labels, decorative panels, and simple overlays on controlled
   *        backgrounds.
   * @avoid Dense text or unpredictable, high-detail backgrounds without
   *        verifying effective contrast.
   */
  "300": {
    /** @token rds.veil.300.color @usage Background fill with alpha already included. */
    color: pair("rgb(255 255 255 / 0.52)", "rgb(26 25 24 / 0.56)"),
    /** @token rds.veil.300.blur @usage Backdrop blur applied to the same layer. */
    blur: "36px",
  },

  /**
   * @group rds.veil.400
   * @role Functional
   * @usage Floating toolbars, navigation flyouts, dropdowns, and popovers.
   * @avoid Assuming contrast is sufficient solely because opacity is higher.
   * @a11y Check text, icons, focus rings, and control boundaries in context.
   */
  "400": {
    /** @token rds.veil.400.color @usage Background fill with alpha already included. */
    color: pair("rgb(255 255 255 / 0.72)", "rgb(26 25 27 / 0.76)"),
    /** @token rds.veil.400.blur @usage Backdrop blur applied to the same layer. */
    blur: "24px",
  },

  /**
   * @group rds.veil.500
   * @role Focused
   * @usage Content-rich floating panels, expanded navigation, and glass modals.
   * @avoid Treating glass as a substitute for structural surface separation
   *        or modal focus management.
   * @a11y Validate text and interactive states over representative backdrops.
   */
  "500": {
    /** @token rds.veil.500.color @usage Background fill with alpha already included. */
    color: pair("rgb(255 255 255 / 0.92)", "rgb(26 25 27 / 0.92)"),
    /** @token rds.veil.500.blur @usage Backdrop blur applied to the same layer. */
    blur: "16px",
  },

  /**
   * @group rds.veil.scrim
   * @role Scrim
   * @usage Blurred background overlay behind floating modals.
   * @avoid Placing over the modal content, using as a glass panel fill, or
   *        silently aliasing to rds.color.scrim.modal.
   * @a11y The modal must remain distinct and keyboard focus contained.
   */
  scrim: {
    /** @token rds.veil.scrim.color @usage Background fill with alpha already included. */
    color: pair("rgb(20 12 17 / 0.52)", "rgb(43 37 41 / 0.52)"),
    /** @token rds.veil.scrim.blur @usage Backdrop blur applied to the same layer. */
    blur: "24px",
  },
} as const satisfies Record<string, VeilTreatment>;

